std::vector<int> data = {1, 2, 3, 4};

// Non-const iterator (mutable access)
// For vector, this is a Random Access Iterator (RAI)
auto start_it = data.begin();

// Iterator points to the first element (1)
int first = *start_it;

// RAI allows arithmetic jumps
start_it += 2;
int third = *start_it; // 3

// Read-only iterator (std::vector::const_iterator)
auto c_start_it = data.cbegin();

// Often implemented as non-virtual member function
// allowing compiler inlining for zero overhead.
